"""Code-owned metadata field contracts and scoped catalogue coverage.

Values live only in product.toml. The register retains every declared catalogue
row; runtime, compiler and unselected conditional fields are dispositions, not
permission to configure Windows. Source IDs refer to the maintained catalogue.
"""
from __future__ import annotations
from dataclasses import dataclass
from types import MappingProxyType

@dataclass(frozen=True, slots=True)
class FieldSpec:
    """Meaning and authority of one field, independently of authored values."""
    key: str
    surface: str
    kind: str
    value_type: str
    owner: str
    applicability: str
    derivation: str
    source_ref: str

